	('debc3e4d-737b-4569-98d4-155ff6ccd0a3', 'Dominorob', 'https://osdxwhodwlabuvyaemum.supabase.co/storage/v1/object/public/avatars/debc3e4d-737b-4569-98d4-155ff6ccd0a3/1779752993856.webp', '2026-05-25 23:42:56.082791+00', 'Addicted to Foiling.  Currently riding a Fliteboard Ultra L3. 
INSERT INTO "public"."spots" ("id", "created_at", "created_by", "name", "description", "status", "lat", "lng", "attributes", "average_rating", "rating_count", "last_verified_at", "source_locale", "user_id") VALUES
	('9282c231-9afa-49c4-99f3-9066dc9375fc', '2026-05-25 02:35:24.115116+00', '9945749f-0a3c-4c69-a834-f541754653d1', 'Tarpon Basin', NULL, 'ALLOWED', 25.11641959469233, -80.4235373488775, '{"food": false, "parking": true, "website": "", "charging": false, "description": "Beach access only available for members of the community. You''d need to rent an AirBnB.\nThere''s a few picnic tables where you can assemble the board.", "parking_distance": "<10m"}', 0.0, 0, '2026-05-25 02:35:24.115116+00', 'en', '9945749f-0a3c-4c69-a834-f541754653d1'),
	('a6b06ced-c1fd-4b6b-a012-a3788002fddc', '2026-05-25 13:39:17.44061+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Wahweap Main Launch Ramp ', NULL, 'ALLOWED', 36.99466464467443, -111.48369156682242, '{"food": false, "rental": false, "parking": true, "website": "https://youtu.be/gf5lfOmJXxE?si=7h20FMac1vFv03oW", "charging": false, "description": "Day-use parking on the bottom left side of this boat launch ramp when water levels are too low for launching boats (water elevation 3553'' and lower).  This is the closest you can park with a 2-wheel-drive vehicle when lake levels are low.  It''s an easy short walk to carry your gear to the beach from the end of the concrete ramp.\nIf lake levels are ≥ 3553 and this launch ramp is in operation for launching boats, use Stateline Launch Ramp instead", "parking_distance": "<50m"}', 0.0, 0, '2026-05-25 13:39:17.44061+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('26e447f1-0b57-44c2-9bf5-85433ce4edd6', '2026-05-17 08:43:31.731383+00', 'e77f1718-7a37-4f77-bc4a-c801968fbf79', 'Geheimer Maasspot', NULL, 'TOLERATED', 50.813956866564325, 5.706324767672754, '{"food": false, "parking": true, "website": "", "charging": false, "description": "Man parkt nicht weit weg. Typischerweise sind hier Angler oder ein paar Badegäste. Hin und wieder trifft man auch Wasserbüffel. "}', 4.0, 1, '2026-05-17 14:49:07.783983+00', 'de', 'e77f1718-7a37-4f77-bc4a-c801968fbf79'),
	('356aa3d2-7800-4329-9f4f-3a313beff23a', '2026-05-24 13:31:40.825147+00', '6c954f46-cb47-4c73-95d6-a26522d85bfa', 'Western Beach', NULL, 'ALLOWED', 36.152257861652885, -5.351595831588753, '{"food": false, "parking": false, "website": "", "charging": false, "description": "One of the best locations in the area for wing foiling, wind sports and E-foiling "}', 0.0, 0, '2026-05-24 13:31:40.825147+00', 'en', '6c954f46-cb47-4c73-95d6-a26522d85bfa'),
	('9c065e2f-b9d7-4e31-badd-3664753e0fdf', '2026-05-24 13:36:52.784116+00', '6c954f46-cb47-4c73-95d6-a26522d85bfa', 'Western Beach', NULL, 'ALLOWED', 36.15193258851599, -5.351026044249039, '{"food": false, "parking": false, "website": "", "charging": false, "description": "Best place in the area for wind sports such as wing foiling and also E-foiling "}', 0.0, 0, '2026-05-24 13:36:52.784116+00', 'en', '6c954f46-cb47-4c73-95d6-a26522d85bfa'),
	('649f85d6-2152-44eb-993c-0e98b5518228', '2026-05-25 14:47:08.166373+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Antelope Point Public Ramp Area ', NULL, 'TOLERATED', 36.966445237006056, -111.44253352341698, '{"food": false, "rental": false, "parking": true, "website": "https://youtube.com/shorts/VMiz6iJGFpc?si=1TT26eq-8w3kO9Nq", "charging": false, "description": "When water levels are lower, You may park directly on the ramp at the bottom on either side untill this ramp resumes operation for boat launch at elevation 3588’\n\nAt lake levels below 3553, you may have a long steep walk to carry your gear\n\nCheck out this video to better understand the accessibility of hand launch craft at elevation 3553’\nhttps://youtu.be/j4etM2hpZcw\n\nFor lake levels bellow 3553'' check out this video\nhttps://youtube.com/shorts/VMiz6iJGFpc?si=RBmOM0N5gMkLGKuz\n\nExperienced eFoil riders only!  The main Channel and Antelope Canyon is not for beginner riders.  If you really want to ride in Antelope Canyon I would suggest going early in the morning, otherwise there will be lots of traffic, mainly kayakers 🛶.  \nThis Canyon is WAKELESS, And technically marked 5 mph.  Please respect and yield to the paddlers in the canyon and watch out for boats too.  Take it slow and wide around canyon turns.  **Ride in such a way that if you were to fall (regardless of your skill level) You can ensure that your gear will not impact anyone or force anyone to change course.  You may have to take a knee or even stop if it is congested and tight... This is a good general rule regardless of where you ride.\n\nReach out to Jeremy, eFoil Lake Powell (Instagram, tiktok, and YouTube) if you have questions or looking for someone to glide with\n"}', 0.0, 0, '2026-05-25 14:47:08.166373+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('d4f987f2-54d1-4546-83ea-aeb8b439b6cb', '2026-05-25 02:37:04.365686+00', '9945749f-0a3c-4c69-a834-f541754653d1', 'Sky Bridge', NULL, 'ALLOWED', 27.654343983812694, -82.67789002409003, '{"food": false, "parking": true, "website": "", "charging": false, "description": "Don''t go left as it''s shallow around the small island. Go right, under the bridge and then left or right. Plenty of deep water."}', 0.0, 0, '2026-05-25 02:37:04.365686+00', 'en', '9945749f-0a3c-4c69-a834-f541754653d1'),
	('0e42bdbe-0fea-4900-bb39-c6bb94d80022', '2026-05-25 02:38:44.528035+00', '9945749f-0a3c-4c69-a834-f541754653d1', 'Pass-a-grille', NULL, 'ALLOWED', 27.684131620388058, -82.73613019989254, '{"food": false, "parking": true, "website": "", "charging": false, "description": "Turn right, get to the bay and then you can go left or right. Can be choppy and high current in the inlet during tides."}', 0.0, 0, '2026-05-25 02:38:44.528035+00', 'en', '9945749f-0a3c-4c69-a834-f541754653d1'),
	('aa031d63-98d9-4e50-a80b-8b7240273f97', '2026-05-25 02:41:19.181181+00', '18b026d5-5c5d-4ac0-a524-d34537b7d6d1', 'La Playa', NULL, 'ALLOWED', 23.685576304028302, -109.69442285586184, '{"food": false, "parking": false, "website": "", "charging": false, "description": "you can park right at the waters edge"}', 0.0, 0, '2026-05-25 02:41:19.181181+00', 'en', '18b026d5-5c5d-4ac0-a524-d34537b7d6d1'),
	('a5d7ffc7-3d62-4268-b63c-9a88c50dfbc8', '2026-05-25 02:43:21.052377+00', '9945749f-0a3c-4c69-a834-f541754653d1', 'Bird Key Park', NULL, 'ALLOWED', 27.32774716595084, -82.56085401924624, '{"food": false, "parking": true, "website": "", "charging": false, "description": "An easy to find parking when all nearbu isles are packed. They have a picknick table and a small kayak dock. Ride in the basin in the front or turn right, go under the bridge, pass the millioner houses and get up to inlet. Can be choppy near inlets during tides."}', 0.0, 0, '2026-05-25 02:43:21.052377+00', 'en', '9945749f-0a3c-4c69-a834-f541754653d1'),
	('0af373d9-101b-4b9a-89a8-c90fef9d6511', '2026-05-24 13:53:49.553463+00', '393f83ff-89dd-4cbc-a100-227d547b3ceb', 'Töppersee ', NULL, 'FORBIDDEN', 51.40285689236967, 6.679835931169038, '{"food": false, "parking": false, "website": "", "charging": false, "description": "Sowohl auf dem Töppersee als auch auf dem kleinen, gennant „Tegge“ ist es nicht erlaubt "}', 0.0, 0, '2026-05-24 13:53:49.553463+00', 'de', '393f83ff-89dd-4cbc-a100-227d547b3ceb'),
