	('cc00095a-72b2-4d17-acc0-1b83f7a8ad2a', '2026-05-16 14:36:45.116584+00', 'e77f1718-7a37-4f77-bc4a-c801968fbf79', 'Blausteinsee', NULL, 'FORBIDDEN', 50.8525093023469, 6.267934789045825, '{"food": true, "parking": true, "website": "", "charging": false, "description": "Kein Wassersport erlaubt. ", "parking_distance": "<50m"}', 1.0, 1, '2026-05-16 14:37:02.234474+00', 'de', 'e77f1718-7a37-4f77-bc4a-c801968fbf79'),
	('dad069df-fb82-4ec5-85af-c8541f2f5add', '2026-05-23 09:10:43.245455+00', 'a5b8a32a-975e-48a8-83c8-90202a77e22f', 'Xanten Südsee', NULL, 'ALLOWED', 51.68343317741332, 6.4386260158406685, '{"food": true, "parking": true, "website": "https://www.f-z-x.de/", "charging": true, "description": "Es gibt die Südsee und die Nordsee in Xanten. An beiden See‘n (die übrigens mit einander verbunden sind) ist eFoil erlaubt. \nEs gibt zwei, extra nur für Wassersportler, eingerichtete Parkplätze. Kostenpflichtig und beinhalten die Benutzung des See‘s. ", "parking_distance": "<50m"}', 5.0, 1, '2026-05-24 13:57:51.34416+00', 'en', 'a5b8a32a-975e-48a8-83c8-90202a77e22f'),
	('217c1da2-5c45-4c5d-9167-707079b9d7a8', '2026-05-24 13:59:10.819019+00', '393f83ff-89dd-4cbc-a100-227d547b3ceb', 'Sechsseenplatte ', NULL, 'FORBIDDEN', 51.381711547711916, 6.799361828978107, '{"food": false, "parking": false, "website": "", "charging": false}', 0.0, 0, '2026-05-24 13:59:10.819019+00', 'de', '393f83ff-89dd-4cbc-a100-227d547b3ceb'),
	('05c2c445-7b68-4b25-b441-7c5d3710a9dc', '2026-05-24 22:21:17.968795+00', 'f3fdd649-a477-4581-a239-96b4679266b8', 'Schildmeer WindsurfSpot', NULL, 'TOLERATED', 53.267387784363564, 6.8286543282339665, '{"food": false, "parking": true, "website": "", "charging": false, "description": "Good entry point and lake has enough depth for foil. Within 80m from parking.", "parking_distance": "<10m"}', 0.0, 0, '2026-05-24 22:21:17.968795+00', 'en', 'f3fdd649-a477-4581-a239-96b4679266b8'),
	('66c5d8ce-4362-49bf-b3ad-2ff3f8485c64', '2026-05-25 13:39:07.174444+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Wahweap Main Launch Ramp ', NULL, 'ALLOWED', 36.99466464467443, -111.48369156682242, '{"food": false, "rental": false, "parking": true, "website": "https://youtu.be/gf5lfOmJXxE?si=7h20FMac1vFv03oW", "charging": false, "description": "Day-use parking on the bottom left side of this boat launch ramp when water levels are too low for launching boats (water elevation 3553'' and lower).  This is the closest you can park with a 2-wheel-drive vehicle when lake levels are low.  It''s an easy short walk to carry your gear to the beach from the end of the concrete ramp.\nIf lake levels are ≥ 3553 and this launch ramp is in operation for launching boats, use Stateline Launch Ramp instead", "parking_distance": "<50m"}', 0.0, 0, '2026-05-25 13:39:07.174444+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('b090d768-8bef-411b-b7ae-1c25a758931c', '2026-05-25 10:41:55.839783+00', '905ccbab-b6eb-4c0a-9aa6-cf1043f92983', 'Slyvan Park', NULL, 'ALLOWED', -36.77761714664633, 174.76953475594513, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Lake Pupuke, Flat water"}', 0.0, 0, '2026-05-25 10:41:55.839783+00', 'en', '905ccbab-b6eb-4c0a-9aa6-cf1043f92983'),
	('bd9bc7e9-1096-40c4-ac9a-7caebdd2c8f2', '2026-05-25 10:54:15.60955+00', 'c6ec95f6-329a-4119-88c7-9fc70e202530', 'Stannagate', NULL, 'ALLOWED', 56.46758482854207, -2.9138169186884966, '{"food": false, "rental": false, "parking": false, "website": "", "charging": false, "description": "Careful on the access, but there are a few paths"}', 0.0, 0, '2026-05-25 10:54:15.60955+00', 'en', 'c6ec95f6-329a-4119-88c7-9fc70e202530'),
	('be9a3879-7209-4d4d-a74d-caadd65e6a85', '2026-05-25 13:48:00.130212+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Green Adventure Sports ', NULL, 'ALLOWED', 36.91589537939376, -111.45715805692102, '{"food": false, "rental": true, "parking": false, "website": "https://adventureelevated.com", "charging": false, "description": "SiFly eFoil rentals, lessons, and sales through a partnership with Adventure Elevated.  Kayaks, SUP, and other adventure gear can be rented or purchased hear along with tours"}', 0.0, 0, '2026-05-25 13:48:00.130212+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('6a7c13bc-500c-45cc-9cff-fac22151a1db', '2026-05-25 14:10:03.333728+00', 'b19edd4a-9bd1-4dc5-9f3d-10a60fd07404', 'Lake Winola', NULL, 'ALLOWED', 41.51231657009413, -75.84607678519714, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Public boat launch with large grassy area to set up the foil. Easy to walk it right in. Lots of free parking. I think technically your board has to be registered but the lake police are only here 2x/year so you should be fine. "}', 0.0, 0, '2026-05-25 14:10:03.333728+00', 'en', 'b19edd4a-9bd1-4dc5-9f3d-10a60fd07404'),
	('2a7861de-3b77-4ec9-9fe2-b169dc93ddb1', '2026-05-25 14:04:17.539872+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Stateline Launch Ramp', NULL, 'ALLOWED', 37.00490725873878, -111.4961392359714, '{"food": false, "rental": false, "parking": true, "website": "https://youtu.be/j4etM2hpZcw", "charging": false, "description": "Use this spot for quick and easy eSurf launching only if water level elevation is at or above 3553'' ! \nAccess to the water becomes a steep rocky cliff when water levels are lower.\nUse Wahweap Main Launch Ramp if water level is bellow 3553’\n\nCheck out this video (website link above) to better understand the accessibility of hand launch craft at elevation 3553’\nhttps://youtu.be/j4etM2hpZcw\n\nYou may park on either side of the bottom of the ramp for daytime use only.  Super quick and easy access to the water when lake levels reach the stated minimum untill water levels reach ~ 4000'' and higher when boat launch activity is restored to this ramp.\n\nReach out to Jeremy, eFoil Lake Powell (Instagram, tiktok, and YouTube) if you have questions or looking for someone to glide with", "parking_distance": "<10m"}', 0.0, 0, '2026-05-25 14:04:17.539872+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('77ade971-8a27-4494-8c12-883e953605ad', '2026-05-25 14:14:00.744612+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Lone Rock Beach ', NULL, 'ALLOWED', 37.01610332964617, -111.53833257635446, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "This is a very soft sandy beach area, popular for many different beach.  Four-Wheel drive vehicle and four-wheel drive experience is recommended, especially if you would like to drive all the way to the water''s edge during times of low lake levels.\nIf you do not have a four-wheel drive vehicle, you may have to walk a good distance in soft sand to reach the water (when lake levels are low).  If you only have a Two-Wheel drive vehicle and/or inexperienced with driving in sand, pay close attention to the texture of the different roads to ensure that you use only the routes that are most solid so you don''t get stuck in the sand.\n\nReach out to Jeremy, eFoil Lake Powell (Instagram, tiktok, and YouTube) if you have questions or looking for someone to glide with", "parking_distance": ">100m"}', 0.0, 0, '2026-05-25 14:14:00.744612+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('fa37fb03-518c-491a-b723-e247ac13624b', '2026-05-25 13:48:07.897297+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Green Adventure Sports ', NULL, 'ALLOWED', 36.9158953793938, -111.457158056921, '{"food": false, "rental": true, "parking": true, "website": "https://adventureelevated.com", "charging": false, "description": "SiFly eFoil rentals, lessons, and sales through a partnership with Adventure Elevated.  Kayaks, SUP, and other adventure gear can be rented or purchased hear along with tours", "parking_distance": "<10m"}', 5.0, 1, '2026-05-25 13:52:58.915382+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
	('41db274b-c1e6-4523-9ed3-9fd8b0f019f7', '2026-05-26 11:13:37.389187+00', '17a80d84-65b2-483c-b5e2-14f44ba17f3a', 'Wasserzugang', NULL, 'ALLOWED', 52.50115802495793, 13.208776473945306, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Parken nur in angrenzenden Straßen.", "parking_distance": "<100m"}', 0.0, 0, '2026-05-26 11:13:37.389187+00', 'de', '17a80d84-65b2-483c-b5e2-14f44ba17f3a'),
	('eb397dd1-b91e-497c-966e-603abb1b8c29', '2026-05-25 19:50:32.32136+00', 'da01ed98-3834-4347-9514-af25db1cce04', 'Lull eFoil', NULL, 'ALLOWED', 44.895891436458214, 13.803072159352553, '{"food": true, "rental": true, "parking": true, "website": "https://www.efoilistria.com", "charging": true, "description": "Lull eFoil Croatia.\nGive us a call and we can organize netrance to the camping spot. You can use electrcity and water. There''s bar and pizzeria near buy.", "parking_distance": "<50m"}', 0.0, 0, '2026-05-25 19:50:32.32136+00', 'en', 'da01ed98-3834-4347-9514-af25db1cce04'),
	('10af30b2-7720-42d3-92fb-18fdb9cad89f', '2026-05-25 20:12:25.226697+00', 'fdd5582d-11a2-40fd-8fba-e46d345db796', 'Wassersuppe', NULL, 'ALLOWED', 52.66826283851657, 12.377148368144049, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Man kann direkt vor Ort parken, es gibt 4 Wohnmobilstellplätze und eine Badewiese, Sitzmöglichkeiten und ein Beachvolleyballfeld.\nMan kommt über den Sandstrand direkt ins Wasser und kann den gesamten 11km langen See abfoilen. Inmitten herrlicher Natur und mit toller Landschaft.", "parking_distance": "<10m"}', 0.0, 0, '2026-05-25 20:12:25.226697+00', 'de', 'fdd5582d-11a2-40fd-8fba-e46d345db796'),
	('3ab8e9f9-a408-4c9e-9d9c-225801afdbd7', '2026-05-25 20:18:20.196105+00', 'fdd5582d-11a2-40fd-8fba-e46d345db796', 'Badestelle Böhne', NULL, 'ALLOWED', 52.55795160526861, 12.309591456738417, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Man kann 20m entfernt auf einem kleinen Parkplatz parken und kommt direkt ans Wasser. Man kann in beide Richtungen auf der schön geschwungenen Havel foilen und am Ufer Wasservögel beobachten."}', 0.0, 0, '2026-05-25 20:18:20.196105+00', 'de', 'fdd5582d-11a2-40fd-8fba-e46d345db796'),
	('234b4c1c-a8f2-49e7-96da-b85b12784e90', '2026-05-25 23:46:32.602475+00', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3', 'Malabar Boat Ramp', NULL, 'ALLOWED', -33.96601655641917, 151.25291403497357, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Park on Bay Parade, easy walk down the ramp and deepwater entry.  Great rolling waves on the north side of the bay.  Watch for Shallow reef on low tide. Watch for swimmers too!"}', 0.0, 0, '2026-05-25 23:46:32.602475+00', 'en', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3'),
	('91c12b21-f1d7-4146-9796-e58ce374a835', '2026-05-25 23:49:12.661057+00', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3', 'Gordons Bay/ Clovelly reef', NULL, 'ALLOWED', -33.91564857553156, 151.2646646194848, '{"food": false, "rental": false, "parking": true, "website": "", "charging": false, "description": "Heaps of parking. Long-ish walk in and challenging entry if the waves are big.  Bombie off the south headland has a cracker wave, but sometimes a bit shallow. Watch for swimmers, divers and snorkelers", "parking_distance": "<50m"}', 0.0, 0, '2026-05-25 23:49:12.661057+00', 'en', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3'),
	('f38ac18f-2e83-4750-83fe-6109614abe9c', '2026-05-25 23:54:20.609657+00', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3', 'Yarra Bay', NULL, 'TOLERATED', -33.980249645680125, 151.22877851856288, '{"food": true, "rental": false, "parking": true, "website": "", "charging": false, "description": "Park in the Yarra bay sailing club parking area.  Nice flat water and good for learning.  Water quality terrible after heavy rain.  e-foils probably not allowed as categorised as a PWC, but tolerated. "}', 0.0, 0, '2026-05-25 23:54:20.609657+00', 'en', 'debc3e4d-737b-4569-98d4-155ff6ccd0a3'),
