	('c8147fa7-684c-40ca-8f04-8feca8fddee1', '2026-05-25 13:39:25.949463+00', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3', 'Wahweap Main Launch Ramp ', NULL, 'ALLOWED', 36.9946646446744, -111.483691566822, '{"food": true, "rental": false, "parking": true, "website": "https://youtu.be/gf5lfOmJXxE?si=7h20FMac1vFv03oW", "charging": true, "description": "Day-use parking on the bottom left side of this boat launch ramp when water levels are too low for launching boats (water elevation 3553'' and lower).  This is the closest you can park with a 2-wheel-drive vehicle when lake levels are low.  It''s an easy short walk to carry your gear to the beach from the end of the concrete ramp.\nIf lake levels are ≥ 3553 and this launch ramp is in operation for launching boats, use Stateline Launch Ramp instead\n\nFor a video example of parking and setting up an eFoil check out the web link above https://youtu.be/gf5lfOmJXxE?si=fzQkPvOON0jMam3k\n\nFood and charging available at the hotel lobby on the ridge above the launch ramp.\n\nReach out to Jeremy, eFoil Lake Powell (Instagram, tiktok, and YouTube) if you have questions or looking for someone to glide with", "parking_distance": "<50m"}', 0.0, 0, '2026-05-25 13:39:25.949463+00', 'en', 'acd666bb-7bf1-457f-94a2-a91a0720e9d3'),
